function singleMailbox(value) {
  if (typeof value !== "string" || /[\r\n\x00]/.test(value)) return "";
  const text = value.trim();
  const named = text.match(/^(?:[^<>,;]+|"[^"\r\n]+")\s*<([^<>]+)>$/);
  const address = named ? named[1] : text;
  return /^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+$/.test(address) &&
    address.length <= 254
    ? address
    : "";
}
export default (settings) => {
  if (
    !settings.folder.trim() ||
    !singleMailbox(settings.reviewer) ||
    !singleMailbox(settings.mailbox) ||
    settings.reviewer.endsWith(".invalid") ||
    settings.mailbox.endsWith(".invalid") ||
    settings.reviewer.toLowerCase() === settings.mailbox.toLowerCase() ||
    !/^[A-Za-z0-9_-]{1,100}$/.test(settings.collection) ||
    settings.collection === "YOUR_QDRANT_COLLECTION" ||
    !/^[A-Za-z0-9_.-]{1,80}$/.test(settings.payloadKey) ||
    !["text-embedding-ada-002", "text-embedding-3-small", "text-embedding-3-large"].includes(
      settings.embeddingModel,
    )
  ) {
    throw Error("Set the approved mailbox, Gmail reviewer, and Qdrant collection settings.");
  }
  return settings;
};

