function singleMailbox(value) {
  if (typeof value !== "string" || /[\r\n\x00]/.test(value)) return "";
  const text = value.trim();
  const named = text.match(/^(?:[^<>,;]+|"[^"\r\n]+")\s*<([^<>]+)>$/);
  const address = named ? named[1] : text;
  return /^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+$/.test(address) &&
    address.length <= 254
    ? address
    : "";
}

function plainMail(text, html) {
  const source =
    typeof text === "string" && text.trim()
      ? text
      : String(html ?? "")
          .replace(/<(script|style|head)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, "")
          .replace(/<br\s*\/?>|<\/(?:p|div|li|h[1-6]|tr)>/gi, "\n")
          .replace(/<[^>]*>/g, "")
          .replace(
            /&(?:amp|lt|gt|quot|apos|nbsp|#39);/gi,
            (value) =>
              ({ amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " ", "#39": "'" })[
                value.slice(1, -1).toLowerCase()
              ],
          );
  return source
    .replace(/\r\n?/g, "\n")
    .replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function checkedMail({ sender, subject, messageId, text, html, uid, truncated }) {
  sender = singleMailbox(sender);
  if (
    !sender ||
    truncated ||
    !Number.isSafeInteger(uid) ||
    uid < 1 ||
    typeof subject !== "string" ||
    !subject.trim() ||
    /[\r\n\x00-\x1f\x7f]/.test(subject) ||
    subject.length > 250 ||
    typeof messageId !== "string" ||
    !/^<[^<>\s@]+@[^<>\s@]+>$/.test(messageId) ||
    messageId.length > 240 ||
    [text, html].some((value) => typeof value === "string" && value.length > 60000)
  )
    return null;
  const body = plainMail(text, html);
  if (!body || body.length > 24000) return null;
  return { sender, subject, messageId, uid, body };
}

async function nextPendingMail(context, folder) {
  const action = (name, input) => context.actions.call("generic_imap." + name, input);
  const status = await action("get_folder_status", { folder });
  if (
    status.folder !== folder ||
    !/^\d+$/.test(String(status.uidValidity ?? "")) ||
    !Number.isSafeInteger(status.uidNext) ||
    status.uidNext < 1
  )
    throw Error("IMAP mailbox identity is unavailable");
  const validity = String(status.uidValidity);
  const cursorKey = "mailbox:" + folder;
  const current = await context.state.get(cursorKey);
  if (current == null) {
    await context.state.insert(cursorKey, { validity, uid: status.uidNext - 1 });
    return null;
  }
  if (current.validity !== validity || current.uid >= status.uidNext)
    throw Error("IMAP mailbox identity changed. Check the mailbox before resetting its cursor.");
  let beforeUid, candidate;
  for (let count = 0; count < 10; count++) {
    const page = await action("search_emails", {
      folder,
      unseen: true,
      limit: 50,
      ...(beforeUid === undefined ? {} : { beforeUid }),
    });
    if (
      page.folder !== folder ||
      !Array.isArray(page.emails) ||
      page.emails.some(
        (item) =>
          !Number.isSafeInteger(item.uid) ||
          item.uid < 1 ||
          (beforeUid !== undefined && item.uid >= beforeUid),
      )
    ) {
      throw Error("IMAP returned an invalid result page");
    }
    for (const item of page.emails)
      if (
        item.uid > current.uid &&
        item.uid < status.uidNext &&
        (!candidate || item.uid < candidate.uid)
      )
        candidate = item;
    if (page.nextBeforeUid == null || page.nextBeforeUid <= current.uid) {
      if (!candidate) return null;
      const mail = await action("get_email", { folder, uid: candidate.uid });
      const confirmed = await action("get_folder_status", { folder });
      if (
        confirmed.folder !== folder ||
        String(confirmed.uidValidity) !== validity ||
        mail.folder !== folder ||
        mail.uid !== candidate.uid ||
        mail.messageId !== candidate.messageId
      )
        throw Error("IMAP returned a different message than the selected inbox item");
      const key = folder + ":" + validity + ":" + candidate.uid;
      if (!(await context.state.insert("intake:" + key, true))) return null;
      await context.state.set(cursorKey, { validity, uid: candidate.uid });
      const normalized = checkedMail({ ...mail, sender: mail.from?.email });
      return normalized ? { ...normalized, key } : null;
    }
    if (
      !Number.isSafeInteger(page.nextBeforeUid) ||
      page.nextBeforeUid < 1 ||
      (beforeUid !== undefined && page.nextBeforeUid >= beforeUid)
    )
      throw Error("IMAP returned a non-advancing cursor");
    beforeUid = page.nextBeforeUid;
  }
  throw Error(
    "IMAP has more than 500 unread items ahead of the cursor. Review the backlog before resuming.",
  );
}
export default async ({ folder, reviewer, mailbox }, context) => {
  const mail = await nextPendingMail(context, folder);
  return {
    mail,
    eligible:
      mail != null &&
      ![reviewer, mailbox].some((address) => address.toLowerCase() === mail.sender.toLowerCase()),
  };
};

