function smtpAccepted(result, to) {
  if (
    !result ||
    !Array.isArray(result.accepted) ||
    result.accepted.length !== 1 ||
    result.accepted[0] !== to ||
    !Array.isArray(result.rejected) ||
    result.rejected.length !== 0 ||
    typeof result.messageId !== "string" ||
    !result.messageId.trim()
  )
    throw Error(
      "SMTP acceptance could not be verified. Check mail logs before considering another send.",
    );
  return result.messageId;
}

function replyHtml(text, escape) {
  return "<p>" + escape(text).replace(/\n\n+/g, "</p><p>").replace(/\n/g, "<br>") + "</p>";
}

function escapeDraftHtml(value) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}
export default async ({ approval }, context) => {
  const { key, sender, subject, draft } = approval.inputs;
  if (!(await context.state.insert("send:" + key, { status: "pending" })))
    return { messageId: null };
  const result = await context.actions.call("generic_imap.send_email", {
    to: [sender],
    subject: "Re: " + subject,
    html: replyHtml(draft, escapeDraftHtml),
    text: draft,
  });
  const messageId = smtpAccepted(result, sender);
  await context.state.set("send:" + key, { status: "accepted", messageId });
  return { messageId };
};

