  ) {
    throw Error("The model returned the same rejected reply. Draft the response manually.");
  }
  return draft;
}

function reviewText(mail, summary, draft) {
  return (
    "Original sender: " +
    mail.sender +
    "\nSubject: " +
    mail.subject +
    "\n\nOriginal message\n" +
    mail.body +
    "\n\nSummary\n" +
    summary +
    "\n\nProposed reply\n" +
    draft
  );
}
export default async ({ original, previous }, context) => {
  if (
    previous &&
    (previous.action !== "reject" ||
      previous.inputs.key !== original.key ||
      typeof previous.comment !== "string" ||
      previous.comment.trim() !== previous.inputs.reviewCode)
  ) {
    throw Error("The rejection code did not match this draft.");
  }
  const data = {
    summary: original.summary,
    evidence: original.evidence,
    priorDraft: previous?.inputs.draft,
  };
  const response = await context.actions.call("openai.create_response", evidenceDraftRequest(data));
  const draft = revisionDraft(response, data, structuredDraftReply, checkModelText);
  const bytes = new Uint8Array(12);
  crypto.getRandomValues(bytes);
  return {
    key: original.key,
    sender: original.sender,
    subject: original.subject,
    draft,
    review: reviewText(original, original.summary, draft),
    reviewCode: Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join(""),
  };
};

