    to: reviewer,
    subject: "[Approval required] Draft 3: " + inputs.subject,
    body,
    isHtml: false,
  });
  if (typeof result.messageId !== "string" || !result.messageId.trim())
    throw Error("Gmail review delivery is unconfirmed.");
  return { messageId: result.messageId };
};

